mapper.sql:
WHERE item.course_id = #{courseId}

  AND item.content ILIKE CONCAT('%', #{query}, '%')


  AND item.chapter_id = #{chapterId}


  AND item.question_type = #{questionType, javaType=edu.ai.lms.core.quiz.app.domain.Question$QuestionType, typeHandler=org.apache.ibatis.type.EnumTypeHandler}


  AND level.code = #{cognitiveLevelCode, javaType=edu.ai.lms.core.quiz.app.domain.questionbank.CognitiveLevelCode, typeHandler=org.apache.ibatis.type.EnumTypeHandler}


  AND item.source_type = #{sourceType, javaType=edu.ai.lms.core.quiz.app.domain.questionbank.QuestionBankSourceType, typeHandler=org.apache.ibatis.type.EnumTypeHandler}

mapper.select:
SELECT 
FROM edu.question_drafts item
LEFT JOIN edu.cognitive_levels level ON level.id = item.cognitive_level_id


  AND EXISTS (
    SELECT 1 FROM edu.question_draft_learning_outcomes link
    WHERE link.question_draft_id = item.id
      AND link.learning_outcome_id = #{learningOutcomeId}
  )

ORDER BY item.updated_at DESC, item.id
LIMIT #{size} OFFSET #{offset}

SELECT , item.origin_draft_id, item.validated_by, item.validated_at FROM edu.question_bank_questions item JOIN edu.cognitive_levels level ON level.id = item.cognitive_level_id
AND EXISTS ( SELECT 1 FROM edu.question_bank_question_learning_outcomes link WHERE link.question_bank_question_id = item.id AND link.learning_outcome_id = #{learningOutcomeId} )
ORDER BY item.updated_at DESC, item.id LIMIT #{size} OFFSET #{offset}

SELECT CASE WHEN EXISTS (
  SELECT 1 FROM edu.question_drafts item
  WHERE item.course_id = #{courseId}
    AND LOWER(BTRIM(item.content)) = LOWER(BTRIM(#{content}))
    AND item.id != #{excludedItemId}
) THEN 1 ELSE 0 END

SELECT CASE WHEN EXISTS (
  SELECT 1 FROM edu.question_bank_questions item
  WHERE item.course_id = #{courseId}
    AND LOWER(BTRIM(item.content)) = LOWER(BTRIM(#{content}))
) THEN 1 ELSE 0 END

SELECT id, code, name, sort_order
FROM edu.cognitive_levels
WHERE code = #{code, javaType=edu.ai.lms.core.quiz.app.domain.questionbank.CognitiveLevelCode, typeHandler=org.apache.ibatis.type.EnumTypeHandler}

mapper.delete:
DELETE FROM edu.question_drafts
WHERE id = #{item.id}
  AND course_id = #{item.courseId}
  AND version = #{expectedVersion}
